            prompt: { en: 'Revenue grew from 60,000 SAR to 75,000 SAR. What is the growth rate in percent? (Enter a number, sign included if negative)', ar: 'نما الإيراد من 60000 ريال إلى 75000 ريال. ما معدل النمو بالمئة؟ (أدخل رقماً مع الإشارة إن كانت سالبة)' },
            accept: ['25', '25%'],
            solution: { en: '(75,000 − 60,000) ÷ 60,000 × 100 = 15,000 ÷ 60,000 × 100 = +25 percent.', ar: '(75000 − 60000) ÷ 60000 × 100 = 15000 ÷ 60000 × 100 = +25 بالمئة.' },
